// The German deck in the "Pixelstil" (ADR 0010, 0014): flat pixel art on a
// 33 × 49.5 grid, one art pixel = 2 × 2 CSS px at the 66 × 99 hand size.
// The art is generated by tools/cardart/ into ./pixelcards.gen.ts; this
// module turns it into a hidden sprite of <symbol>s once, and cards then
// only reference the symbols with <use>, which keeps the DOM small. Pure
// drawing, no rules.
//
// A face is three layers so card modifications (./cards.ts) can lie in
// between: paper (drawn by ./cards.ts, some modifications tint it), the
// picture (f-…; the "Untot" picture u-…, the open "Wandelkarte" w-…, a
// settled one ws-… per suit) and the corner index (x-…, wx-… for the open
// Wandelkarte; a settled one uses its suit's x-…). The card's frame (1 px dark
// line, hard shadow) comes from CSS and lies outside the art, so the art
// keeps its integer scale.

import { de } from '../i18n';
import type { Rank, Suit } from '../types';
import { backSymbols } from './backs';
import { peopleSymbols } from './people';
import { modIconBody, ICON_MODS } from './fxart';
import { ART_FACES, ART_GLYPHS, ART_H, ART_INK, ART_PALETTE, ART_PAPER, ART_SIGNS, ART_UNDEAD, ART_W, ART_WILD, ART_WILD_BIG, ART_WILD_INK, ART_WILD_SETTLED } from './pixelcards.gen';

export const SUITS: Suit[] = ['Clubs', 'Spades', 'Hearts', 'Diamonds'];
export const RANKS: Rank[] = ['7', '8', '9', 'T', 'J', 'Q', 'K', 'A'];

const CODE: Record<Suit, string> = { Clubs: 'C', Spades: 'S', Hearts: 'H', Diamonds: 'D' };

/** The card in art pixels: 33 wide, 49.5 high (the last half row is paper). */
export const CARD_W = ART_W;
export const CARD_H = ART_H + 0.5;

/** The paper of the deck. */
export const PAPER = ART_PAPER;

const PIXEL_FONT = "'VT323', monospace";

/**
 * Paths of a palette grid: per palette key one path of horizontal runs
 * (crisp rectangles merged per row). `pick` maps a grid letter to the
 * palette key it stands for in this layer, or null.
 */
function gridPaths(rows: string[], pick: (ch: string) => string | null, x0 = 0, y0 = 0, u = 1): string {
  const runs = new Map<string, string>();
  rows.forEach((row, y) => {
    let x = 0;
    while (x < row.length) {
      const key = pick(row[x] ?? '.');
      if (!key) {
        x++;
        continue;
      }
      let k = x;
      while (k + 1 < row.length && pick(row[k + 1] ?? '.') === key) k++;
      const n = (k - x + 1) * u;
      runs.set(key, (runs.get(key) ?? '') + `M${x0 + x * u} ${y0 + y * u}h${n}v${u}h-${n}z`);
      x = k + 1;
    }
  });
  return [...runs].map(([key, d]) => `<path d="${d}" fill="${ART_PALETTE[key] ?? '#000'}"/>`).join('');
}

/** Capitals A-Z are the corner index, "." is paper, any other key is picture. */
const INDEX_KEY = /^[A-Z]$/;
const lower = (ch: string): string | null => (ch !== '.' && !INDEX_KEY.test(ch) ? ch : null);
const upper = (ch: string): string | null => (INDEX_KEY.test(ch) ? ch.toLowerCase() : null);
const same = (ch: string): string | null => (ch !== '.' ? ch : null);

// ------------------------------------------------------------ suit signs

/** A suit sign (the held sign of the deck), centred in an 8 × 8 box. */
function signPaths(suit: Suit): string {
  const rows = ART_SIGNS[CODE[suit]] ?? [];
  const w = rows[0]?.length ?? 0;
  return gridPaths(rows, same, (8 - w) / 2, (8 - rows.length) / 2);
}

// --------------------------------------------------------------- the faces

function faceRows(suit: Suit, rank: Rank): string[] {
  return ART_FACES[`${CODE[suit]}${rank}`] ?? [];
}

/**
 * The face for tiny cards (about 16 to 26 px wide), where the picture
 * would only turn into noise: the corner index letter and the suit sign,
 * both big.
 */
function smallFace(suit: Suit, rank: Rank): string {
  return smallBody(rank, ART_INK[CODE[suit]] ?? 'k', ART_SIGNS[CODE[suit]] ?? []);
}

function smallBody(rank: Rank, ink: string, sign: string[]): string {
  const glyph = (ART_GLYPHS[rank] ?? []).map((r) => r.replace(/x/g, ink));
  const gw = (glyph[0]?.length ?? 0) * 4;
  const sw = (sign[0]?.length ?? 0) * 2;
  return gridPaths(glyph, same, (CARD_W - gw) / 2, 4, 4) + gridPaths(sign, same, (CARD_W - sw) / 2, 41 - sign.length * 2, 2);
}

// ------------------------------------------------------------ Doppelgänger

const hexRgb = (c: string): [number, number, number] => [1, 3, 5].map((i) => parseInt(c.slice(i, i + 2), 16)) as [number, number, number];
const rgbHex = (r: number, g: number, b: number): string => `#${[r, g, b].map((v) => Math.round(v).toString(16).padStart(2, '0')).join('')}`;
/** Violet shades from dark to light, the mirror image's palette. */
const MIRROR_RAMP = ['#1e1630', '#3d2f5e', '#6a58a0', '#a493d6', '#e4def5'].map(hexRgb);

/** A colour of the deck's palette as the violet shade of its lightness. */
function mirrorShade(colour: string): string {
  const [r, g, b] = hexRgb(colour);
  const t = ((0.3 * r + 0.59 * g + 0.11 * b) / 255) * (MIRROR_RAMP.length - 1);
  const i = Math.min(MIRROR_RAMP.length - 2, Math.floor(t));
  const f = t - i;
  const a = MIRROR_RAMP[i] ?? [0, 0, 0];
  const c = MIRROR_RAMP[i + 1] ?? [0, 0, 0];
  return rgbHex(a[0] + (c[0] - a[0]) * f, a[1] + (c[1] - a[1]) * f, a[2] + (c[2] - a[2]) * f);
}

/**
 * "Doppelgänger" (DG-A, 03.11.2026): the left half of the picture as
 * printed, the right half its mirror image in violet shades on lavender
 * paper, a dashed mirror edge in the middle.
 */
function mirrorBody(rows: string[]): string {
  const left = rows.map((r) => [...r].map((c, x) => (x < 16 ? c : '.')).join(''));
  const right = rows.map((r) => [...r].map((_c, x) => (x >= 17 ? (r[32 - x] ?? '.') : '.')).join(''));
  const shaded = gridPaths(right, lower).replace(/fill="(#[0-9a-fA-F]{6})"/g, (_m, c: string) => `fill="${mirrorShade(c)}"`);
  let seam = '';
  for (let y = 0; y < 49; y++) if (y % 4 !== 3) seam += `M16 ${y}h1v1h-1z`;
  return `<rect x="17" y="0" width="16" height="${CARD_H}" fill="#e9e5f4"/>${gridPaths(left, lower)}${shaded}<path d="${seam}" fill="#8a7fb0"/>`;
}

// ------------------------------------------------------------- other faces

function blankBody(): string {
  return `<rect width="120" height="180" fill="#dcd9cf"/>
<rect x="10" y="10" width="100" height="160" fill="url(#blank-hatch)"/>
<rect x="14" y="76" width="92" height="30" fill="#dcd9cf"/>
<text x="60" y="98" text-anchor="middle" font-family="${PIXEL_FONT}" font-size="25" fill="#6f7479" class="idx">${de.card.blank}</text>`;
}

// --------------------------------------------------------- modifications

/** Icons of the card modifications (./fxart.ts), for lists beside the cards. */
export function modIconId(mod: string): string {
  return ICON_MODS.includes(mod) ? `m-${mod}` : 'm-other';
}

function modSymbols(): string {
  const icons = ICON_MODS.map((id) => `<symbol id="m-${id}" viewBox="0 0 16 16" shape-rendering="crispEdges">${modIconBody(id) ?? ''}</symbol>`).join('');
  return `${icons}<symbol id="m-other" viewBox="0 0 16 16" shape-rendering="crispEdges"><rect width="16" height="16" fill="#0b0c0e"/><rect x="1" y="1" width="14" height="14" fill="#6a6a5a"/><rect x="7" y="7" width="2" height="2" fill="#fff"/></symbol>`;
}

// ---------------------------------------------------------------- sprite

/** The hidden SVG sprite with every symbol of the deck. */
export function spriteSvg(): string {
  const box = `viewBox="0 0 ${CARD_W} ${CARD_H}" shape-rendering="crispEdges"`;
  const suits = SUITS.map((s) => `<symbol id="s-${CODE[s]}" viewBox="0 0 8 8" shape-rendering="crispEdges">${signPaths(s)}</symbol>`).join('');
  const faces = SUITS.flatMap((s) =>
    RANKS.map((r) => {
      const rows = faceRows(s, r);
      const id = `${CODE[s]}${r}`;
      return (
        `<symbol id="f-${id}" ${box}>${gridPaths(rows, lower)}</symbol>` +
        `<symbol id="x-${id}" ${box} data-rank="${de.rankShort[r]}">${gridPaths(rows, upper)}</symbol>` +
        `<symbol id="t-${id}" ${box}>${smallFace(s, r)}</symbol>` +
        (ART_UNDEAD[id] ? `<symbol id="u-${id}" ${box}>${gridPaths(ART_UNDEAD[id] ?? [], lower)}</symbol>` : '') +
        `<symbol id="d-${id}" ${box}>${mirrorBody(rows)}</symbol>`
      );
    }),
  ).join('');
  // "Wandelkarte", open: the harlequin in all four suit colours, its own index (rank in black, four suit pips).
  const wild = RANKS.map((r) => {
    const rows = ART_WILD[r] ?? [];
    return (
      `<symbol id="w-${r}" ${box}>${gridPaths(rows, lower)}</symbol>` +
      `<symbol id="wx-${r}" ${box}>${gridPaths(rows, upper)}</symbol>` +
      `<symbol id="wt-${r}" ${box}>${smallBody(r, ART_WILD_INK, ART_WILD_BIG)}</symbol>`
    );
  }).join('');
  // "Wandelkarte", settled: the same picture in one suit's shades; index and tiny face are the suit's own.
  const settled = SUITS.flatMap((s) => RANKS.map((r) => `<symbol id="ws-${CODE[s]}${r}" ${box}>${gridPaths(ART_WILD_SETTLED[`${CODE[s]}${r}`] ?? [], lower)}</symbol>`)).join('');
  return `<svg class="sprite" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false" width="0" height="0" style="position:absolute;width:0;height:0;overflow:hidden">
<defs>
<pattern id="blank-hatch" width="8" height="8" patternUnits="userSpaceOnUse">
<path d="M0 0h4v4h-4z" fill="#cbc7bb"/></pattern>
</defs>
${suits}${faces}${wild}${settled}
${backSymbols()}
<symbol id="f-blank" viewBox="0 0 120 180" shape-rendering="crispEdges">${blankBody()}</symbol>
${modSymbols()}
${peopleSymbols()}
</svg>`;
}

/** Symbol id of a face's picture. */
export function faceId(suit: Suit, rank: Rank): string {
  return `f-${CODE[suit]}${rank}`;
}

/** Symbol id of a face's corner index. */
export function indexId(suit: Suit, rank: Rank): string {
  return `x-${CODE[suit]}${rank}`;
}

/** Symbol id of the face for tiny cards (index letter and sign, big). */
export function smallFaceId(suit: Suit, rank: Rank): string {
  return `t-${CODE[suit]}${rank}`;
}

/** Symbol id of the "Untot" picture of a card (zombie figure, rotten pips), or null if there is none. */
export function undeadFaceId(suit: Suit, rank: Rank): string | null {
  const id = `${CODE[suit]}${rank}`;
  return ART_UNDEAD[id] ? `u-${id}` : null;
}

/** Symbol id of the "Doppelgänger" picture of a card (its mirror image, DG-A). */
export function mirrorFaceId(suit: Suit, rank: Rank): string {
  return `d-${CODE[suit]}${rank}`;
}

/**
 * Symbol ids of a "Wandelkarte" face: picture, corner index, tiny face.
 * Open (no suit): the harlequin; settled into `suit`: the picture in that
 * suit's shades with the suit's normal index and tiny face.
 */
export function wildFaceIds(rank: Rank, suit: Suit | null = null): { picture: string; index: string; small: string } {
  if (suit) return { picture: `ws-${CODE[suit]}${rank}`, index: indexId(suit, rank), small: smallFaceId(suit, rank) };
  return { picture: `w-${rank}`, index: `wx-${rank}`, small: `wt-${rank}` };
}

export function suitId(suit: Suit): string {
  return `s-${CODE[suit]}`;
}

let installed = false;

/** Put the sprite into the document once. */
export function installSprite(): void {
  if (installed || typeof document === 'undefined') return;
  installed = true;
  document.body.insertAdjacentHTML('afterbegin', spriteSvg());
}
